using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Security.Cryptography;
using System.Text.Json;
using HPR.GameplaySuite;
using UnityEditor;

// Execute ACTUAL exact method source (generated by extract_exact_method.py)
// against controlled fake Unity APIs. Never claim native Unity runtime.
public static class Program
{
    private static void Require(bool value, string reason)
    {
        if (!value) throw new Exception("FAKE_EDITOR_CONTRACT_FAILED: " + reason);
    }
    private static string Sha(byte[] value) => Convert.ToHexString(SHA256.HashData(value));
    private static Dictionary<string, object> Run(string projectBase, string scenario)
    {
        string root = Path.Combine(projectBase, scenario);
        Require(!Directory.Exists(root), "unique synthetic project already exists");
        Directory.CreateDirectory(root);
        AssetDatabase.Start(root, scenario);
        string originalA = Sha(AssetDatabase.FileBytes(AssetDatabase.VendorA));
        string originalZ = Sha(AssetDatabase.FileBytes(AssetDatabase.VendorZ));
        string existingBuyer = scenario == "initial-collision"
            ? Sha(AssetDatabase.FileBytes(AssetDatabase.CustomerA)) : "";
        string message = "";
        bool operationSucceeded = false;
        try
        {
            var result = HprSuiteIntegrationGuide.CopySampleToCustomerPath(
                AssetDatabase.VendorA, AssetDatabase.CustomerA);
            operationSucceeded = result != null;
        }
        catch (Exception error) when (error is IOException || error is InvalidOperationException)
        {
            message = error.Message;
        }
        Require(Sha(AssetDatabase.FileBytes(AssetDatabase.VendorA)) == originalA &&
                Sha(AssetDatabase.FileBytes(AssetDatabase.VendorZ)) == originalZ,
                "vendor source was rewritten");
        bool copiedA = AssetDatabase.FileExists(AssetDatabase.CustomerA);
        bool copiedZ = AssetDatabase.FileExists(AssetDatabase.CustomerZ);
        switch (scenario)
        {
            case "normal":
                Require(operationSucceeded, "normal copy did not return an asset");
                Require(copiedA && copiedZ && AssetDatabase.CopyCalls == 2,
                        "normal copy did not create both customer-owned dependencies");
                Require(AssetDatabase.SavedCopies == 2, "normal copy did not save targeted copies");
                break;
            case "partial-false-file":
                Require(!operationSucceeded && copiedA && copiedZ,
                        "partial false return must preserve partial file and previous copy");
                Require(message.Contains("last attempted output may also exist") &&
                        message.Contains(AssetDatabase.CustomerZ) &&
                        message.Contains(AssetDatabase.CustomerA),
                        "error did not identify both confirmed and uncertain output paths");
                Require(AssetDatabase.CopyCalls == 2, "expected two attempted calls");
                break;
            case "partial-no-file":
                Require(!operationSucceeded && copiedA && !copiedZ,
                        "false-return without partial file should keep first copied asset");
                Require(message.Contains("may also exist") &&
                        message.Contains(AssetDatabase.CustomerZ),
                        "last uncertain target missing from buyer guidance");
                break;
            case "first-false-no-file":
                Require(!operationSucceeded && !copiedA && !copiedZ,
                        "first failed attempt must not invent a copied file");
                Require(message.Contains("(none confirmed)") &&
                        message.Contains(AssetDatabase.CustomerA),
                        "failed first attempt must identify uncertain file but not claim success");
                break;
            case "race-after-preflight":
                Require(!operationSucceeded && copiedA && copiedZ,
                        "pre-copy recheck should retain previously copied asset and other owner's file");
                Require(AssetDatabase.CopyCalls == 1,
                        "second Unity CopyAsset was called despite intervening new owner file");
                Require(Sha(AssetDatabase.FileBytes(AssetDatabase.CustomerZ)) ==
                        Sha(AssetDatabase.ExternalBuyerBytes),
                        "externally created customer asset was overwritten");
                Require(message.Contains("output became occupied before copying") &&
                        message.Contains(AssetDatabase.CustomerA),
                        "buyer not told which copy succeeded and which became occupied");
                break;
            case "initial-collision":
                Require(!operationSucceeded && AssetDatabase.CopyCalls == 0,
                        "pre-existing buyer asset should fail before first CopyAsset");
                Require(Sha(AssetDatabase.FileBytes(AssetDatabase.CustomerA)) == existingBuyer,
                        "pre-existing buyer asset was overwritten");
                break;
            default: throw new Exception("Unknown synthetic test scenario: " + scenario);
        }
        return new Dictionary<string, object>
        {
            {"scenario", scenario}, {"fake_unity_editor", true},
            {"success", true}, {"source_vendor_unmodified", true},
            {"copy_calls", AssetDatabase.CopyCalls},
            {"targeted_save_calls", AssetDatabase.SavedCopies},
            {"output_a_exists", copiedA}, {"output_z_exists", copiedZ},
            {"operation_reported_success", operationSucceeded},
            {"not_a_real_unity_editor_test", true}
        };
    }
    public static int Main(string[] args)
    {
        if (args.Length != 1 || !Directory.Exists(args[0]))
        {
            Console.Error.WriteLine("An existing private root for synthetic files is required");
            return 3;
        }
        var reports = new List<Dictionary<string, object>>();
        foreach (var scenario in new [] {
            "normal", "partial-false-file", "partial-no-file",
            "first-false-no-file", "race-after-preflight", "initial-collision" })
        {
            reports.Add(Run(args[0], scenario));
        }
        Console.WriteLine(JsonSerializer.Serialize(new {
            status="PASS", scenario_count=reports.Count, results=reports,
            actual_unity_editor_process_executed=false,
            no_asset_database_delete_method_available_in_stub=true,
            warning="Synthetic fake Unity APIs: genuine Unity 6 Editor and concurrent importer acceptance remain unverified"
        }, new JsonSerializerOptions{WriteIndented=true}));
        return 0;
    }
}
